                  {
                    step: "03",
                    icon: BarChart2,
                    title: "Get Ranked Results",
                    desc: "Every candidate gets an overall match score, confidence rating, strengths, skill gaps, and ready-to-use interview questions.",
                    detail: "Ranked best to worst.",
