import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  CheckCircle2, XCircle, FileCheck, Lightbulb,
  ShieldCheck, ShieldAlert, Wand2, Target, AlertCircle,
} from "lucide-react";
import type { Result } from "@/pages/Index";

interface JDAlignedPanelProps {
  result: Result;
  onRewriteJd?: () => void;
}

/* ── Helpers ──────────────────────────────────────────────── */

const getMatchLabel = (score: number) => {
  if (score >= 70) return { text: "Strong match", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
  if (score >= 50) return { text: "Good match", cls: "bg-blue-500/10 text-blue-600 border-blue-200" };
  if (score >= 30) return { text: "Partial match", cls: "bg-amber-500/10 text-amber-600 border-amber-200" };
  return { text: "Weak match", cls: "bg-red-500/10 text-red-600 border-red-200" };
};

const getConfidenceLabel = (c: number) => {
  if (c >= 70) return { text: "High confidence", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
  if (c >= 40) return { text: "Medium confidence", cls: "bg-amber-500/10 text-amber-600 border-amber-200" };
  return { text: "Low confidence", cls: "bg-red-500/10 text-red-600 border-red-200" };
};

const getRecommendation = (score: number, hardFit?: boolean) => {
  if (score >= 70 && hardFit !== false)
    return { text: "Shortlist — strong core fit, gaps are learnable", cls: "bg-emerald-500/10 text-emerald-700 border-emerald-200" };
  if (score >= 50 && hardFit !== false)
    return { text: "Consider — decent match, review before interview", cls: "bg-blue-500/10 text-blue-700 border-blue-200" };
  if (score >= 40)
    return { text: "Review — has strengths but missing critical items", cls: "bg-amber-500/10 text-amber-700 border-amber-200" };
  return { text: "Pass — significant gaps for this role", cls: "bg-red-500/10 text-red-700 border-red-200" };
};

/* ── Component ────────────────────────────────────────────── */

const JDAlignedPanel = ({ result: r, onRewriteJd }: JDAlignedPanelProps) => {
  const matched = (r.matched_must_haves as string[]) || [];
  const missing = (r.missing_must_haves as string[]) || [];
  const strengths = (r.strengths_json || []) as string[];
  const gaps = (r.gaps_json || []) as string[];
  const confidence = r.confidence ?? 0;
  const interviewQs = Array.isArray(r.interview_questions) ? (r.interview_questions as string[]) : [];

  // Must-have stats
  const totalMustHave = matched.length + missing.length;

  // Preferred: use stored data from GPT when available, fallback to derivation
  const matchedPreferred: string[] =
    r.explanation_json?.matched_preferred ??
    strengths.filter((s) => !matched.some((m) => s.toLowerCase().includes(m.toLowerCase()))).slice(0, 5);
  const missingPreferred: string[] =
    r.explanation_json?.missing_preferred ??
    gaps.filter((g) => !missing.some((m) => g.toLowerCase().includes(m.toLowerCase()))).slice(0, 3);
  const totalPreferred = matchedPreferred.length + missingPreferred.length;

  // Risk signals — colour-coded pills
  const risks: { text: string; severity: "red" | "amber" | "green" }[] = [];
  missing.slice(0, 2).forEach((m) => risks.push({ text: `No ${m}`, severity: "red" }));
  missingPreferred.slice(0, 2).forEach((m) => risks.push({ text: `No ${m}`, severity: "amber" }));
  if (matched.length === totalMustHave && totalMustHave > 0)
    risks.push({ text: "All must-haves met", severity: "green" });
  if (confidence >= 70) risks.push({ text: "High confidence score", severity: "green" });
  else if (confidence >= 40) risks.push({ text: "Medium confidence", severity: "amber" });
  else if (confidence > 0) risks.push({ text: "Low confidence score", severity: "red" });
  if (r.scoring_version === "heuristic") risks.push({ text: "Quick scoring only", severity: "amber" });

  const matchLabel = getMatchLabel(r.overall_score);
  const confLabel = getConfidenceLabel(confidence);
  const rec = getRecommendation(r.overall_score, r.hard_fit);

  if (totalMustHave === 0 && !r.explanation_json?.why_ranked_here && risks.length === 0) return null;

  return (
    <div className="rounded-lg border border-border bg-card overflow-hidden">
      {/* ── Header ─────────────────────────────────────────── */}
      <div className="px-4 py-3 border-b border-border bg-muted/30">
        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-2">
            <FileCheck className="h-4 w-4 text-score-jd" />
            <span className="text-xs font-semibold uppercase tracking-wide text-foreground">JD Aligned</span>
          </div>

          {/* Match score */}
          <div className="flex items-center gap-1.5">
            <span className="text-lg font-bold tabular-nums text-foreground">{r.overall_score?.toFixed(0)}%</span>
            <span className="text-[10px] text-muted-foreground leading-tight">Match<br />score</span>
          </div>

          <Badge variant="outline" className={`text-[10px] ${matchLabel.cls}`}>{matchLabel.text}</Badge>
          <Badge variant="outline" className={`text-[10px] ${confLabel.cls}`}>{confLabel.text}</Badge>

          {/* Summary chips */}
          <div className="flex items-center gap-1.5 ml-auto flex-wrap">
            {totalMustHave > 0 && (
              <Badge variant="outline" className="text-[10px] bg-emerald-500/10 text-emerald-600 border-emerald-200">
                {matched.length}/{totalMustHave} must-have
              </Badge>
            )}
            {totalPreferred > 0 && (
              <Badge variant="outline" className="text-[10px] bg-blue-500/10 text-blue-600 border-blue-200">
                {matchedPreferred.length}/{totalPreferred} preferred
              </Badge>
            )}
            {missing.length + missingPreferred.length > 0 && (
              <Badge variant="outline" className="text-[10px] bg-red-500/10 text-red-600 border-red-200">
                {missing.length + missingPreferred.length} not met
              </Badge>
            )}
          </div>
        </div>
      </div>

      {/* ── 4-Column Grid ──────────────────────────────────── */}
      <div className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {/* MUST HAVE */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-emerald-600 font-semibold flex items-center gap-1">
              <ShieldCheck className="h-3 w-3" /> Must Have
            </span>
            <div className="space-y-1.5">
              {matched.map((item, i) => (
                <div key={`m-${i}`} className="flex items-start gap-1.5 text-xs">
                  <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                  <span className="text-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className="text-[9px] shrink-0 bg-emerald-500/10 text-emerald-600 border-emerald-200">
                    Met
                  </Badge>
                </div>
              ))}
              {missing.map((item, i) => (
                <div key={`x-${i}`} className="flex items-start gap-1.5 text-xs">
                  <XCircle className="h-3.5 w-3.5 text-destructive shrink-0 mt-0.5" />
                  <span className="text-muted-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className="text-[9px] shrink-0 bg-red-500/10 text-red-600 border-red-200">
                    Not Met
                  </Badge>
                </div>
              ))}
              {totalMustHave === 0 && (
                <p className="text-xs text-muted-foreground italic">No must-have data</p>
              )}
            </div>
          </div>

          {/* PREFERRED */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-blue-600 font-semibold flex items-center gap-1">
              <Target className="h-3 w-3" /> Preferred
            </span>
            <div className="space-y-1.5">
              {matchedPreferred.map((item, i) => (
                <div key={`pm-${i}`} className="flex items-start gap-1.5 text-xs">
                  <CheckCircle2 className="h-3.5 w-3.5 text-blue-500 shrink-0 mt-0.5" />
                  <span className="text-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className="text-[9px] shrink-0 bg-blue-500/10 text-blue-600 border-blue-200">
                    Met
                  </Badge>
                </div>
              ))}
              {missingPreferred.map((item, i) => (
                <div key={`px-${i}`} className="flex items-start gap-1.5 text-xs">
                  <AlertCircle className="h-3.5 w-3.5 text-amber-500 shrink-0 mt-0.5" />
                  <span className="text-muted-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className="text-[9px] shrink-0 bg-amber-500/10 text-amber-600 border-amber-200">
                    Not Met
                  </Badge>
                </div>
              ))}
              {matchedPreferred.length === 0 && missingPreferred.length === 0 && (
                <p className="text-xs text-muted-foreground italic">No preferred data</p>
              )}
            </div>
          </div>

          {/* AI INSIGHT */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-score-overall font-semibold flex items-center gap-1">
              <Lightbulb className="h-3 w-3" /> AI Insight
            </span>

            {r.explanation_json?.why_ranked_here && (
              <p className="text-[11px] text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
            )}

            {/* Recommendation */}
            <div className={`p-2 rounded text-[11px] font-medium border ${rec.cls}`}>
              <span className="text-[9px] uppercase tracking-wider font-semibold block mb-0.5 opacity-70">Recommendation</span>
              {rec.text}
            </div>

            {/* Interview Focus */}
            {interviewQs.length > 0 && (
              <div className="p-2 rounded bg-purple-500/5 border border-purple-500/20 text-[11px]">
                <span className="text-[9px] uppercase tracking-wider font-semibold text-purple-600 block mb-0.5">
                  Interview Focus
                </span>
                <span className="text-muted-foreground leading-relaxed">{interviewQs[0]}</span>
              </div>
            )}

            {/* Key trade-offs */}
            {r.explanation_json?.key_tradeoffs && (
              <p className="text-[10px] text-muted-foreground leading-relaxed italic">
                {r.explanation_json.key_tradeoffs}
              </p>
            )}
          </div>

          {/* RISK SIGNALS */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-destructive font-semibold flex items-center gap-1">
              <ShieldAlert className="h-3 w-3" /> Risk Signals
            </span>
            <div className="space-y-1.5">
              {risks.map((risk, i) => (
                <div
                  key={i}
                  className={`text-[11px] px-2.5 py-1.5 rounded-md font-medium border ${
                    risk.severity === "red"
                      ? "bg-red-500/10 text-red-600 border-red-200"
                      : risk.severity === "amber"
                        ? "bg-amber-500/10 text-amber-600 border-amber-200"
                        : "bg-emerald-500/10 text-emerald-600 border-emerald-200"
                  }`}
                >
                  {risk.text}
                </div>
              ))}
              {risks.length === 0 && <p className="text-xs text-muted-foreground italic">No risk signals</p>}
            </div>
          </div>
        </div>
      </div>

      {/* ── AI Suggestion Bar ──────────────────────────────── */}
      {missing.length + missingPreferred.length > 0 && onRewriteJd && (
        <div className="px-4 py-2.5 border-t border-border bg-muted/20 flex items-center gap-3 flex-wrap">
          <Lightbulb className="h-3.5 w-3.5 text-amber-500 shrink-0" />
          <p className="text-xs text-muted-foreground flex-1">
