  9→interface JDAlignedPanelProps {
 10→  result: Result;
 11→  onRewriteJd?: () => void;
 12→}
 13→
 14→/* ── Helpers ──────────────────────────────────────────────── */
 15→
 16→const getMatchLabel = (score: number) => {
 17→  if (score >= 70) return { text: "Strong match", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
 18→  if (score >= 50) return { text: "Good match", cls: "bg-blue-500/10 text-blue-600 border-blue-200" };
 19→  if (score >= 30) return { text: "Partial match", cls: "bg-amber-500/10 text-amber-600 border-amber-200" };
 20→  return { text: "Weak match", cls: "bg-red-500/10 text-red-600 border-red-200" };
 21→};
 22→
 23→const getConfidenceLabel = (c: number) => {
 24→  if (c >= 70) return { text: "High confidence", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
 25→  if (c >= 40) return { text: "Medium confidence", cls: "bg-amber-500/10 text-amber-600 border-amber-200" };
 26→  return { text: "Low confidence", cls: "bg-red-500/10 text-red-600 border-red-200" };
 27→};
 28→
 29→const getRecommendation = (score: number, hardFit?: boolean) => {
 30→  if (score >= 70 && hardFit !== false)
 31→    return { text: "Shortlist — strong core fit, gaps are learnable", cls: "bg-emerald-500/10 text-emerald-700 border-emerald-200" };
 32→  if (score >= 50 && hardFit !== false)
 33→    return { text: "Consider — decent match, review before interview", cls: "bg-blue-500/10 text-blue-700 border-blue-200" };
 34→  if (score >= 40)
 35→    return { text: "Review — has strengths but missing critical items", cls: "bg-amber-500/10 text-amber-700 border-amber-200" };
 36→  return { text: "Pass — significant gaps for this role", cls: "bg-red-500/10 text-red-700 border-red-200" };
 37→};
 38→
 39→/* ── Component ────────────────────────────────────────────── */
 40→
 41→const JDAlignedPanel = ({ result: r, onRewriteJd }: JDAlignedPanelProps) => {
 42→  const matched = (r.matched_must_haves as string[]) || [];
 43→  const missing = (r.missing_must_haves as string[]) || [];
 44→  const strengths = (r.strengths_json || []) as string[];
 45→  const gaps = (r.gaps_json || []) as string[];
 46→  const confidence = r.confidence ?? 0;
 47→  const interviewQs = Array.isArray(r.interview_questions) ? (r.interview_questions as string[]) : [];
 48→
 49→  // Must-have stats
 50→  const totalMustHave = matched.length + missing.length;
 51→
 52→  // Preferred: use stored data from GPT when available, fallback to derivation
 53→  const matchedPreferred: string[] =
 54→    r.explanation_json?.matched_preferred ??
 55→    strengths.filter((s) => !matched.some((m) => s.toLowerCase().includes(m.toLowerCase()))).slice(0, 5);
 56→  const missingPreferred: string[] =
 57→    r.explanation_json?.missing_preferred ??
 58→    gaps.filter((g) => !missing.some((m) => g.toLowerCase().includes(m.toLowerCase()))).slice(0, 3);
 59→  const totalPreferred = matchedPreferred.length + missingPreferred.length;
 60→
 61→  // Risk signals — colour-coded pills
 62→  const risks: { text: string; severity: "red" | "amber" | "green" }[] = [];
 63→  missing.slice(0, 2).forEach((m) => risks.push({ text: `No ${m}`, severity: "red" }));
 64→  missingPreferred.slice(0, 2).forEach((m) => risks.push({ text: `No ${m}`, severity: "amber" }));
 65→  if (matched.length === totalMustHave && totalMustHave > 0)
 66→    risks.push({ text: "All must-haves met", severity: "green" });
 67→  if (confidence >= 70) risks.push({ text: "High confidence score", severity: "green" });
 68→  else if (confidence >= 40) risks.push({ text: "Medium confidence", severity: "amber" });
 69→  else if (confidence > 0) risks.push({ text: "Low confidence score", severity: "red" });
 70→  if (r.scoring_version === "heuristic") risks.push({ text: "Quick scoring only", severity: "amber" });
 71→
 72→  const matchLabel = getMatchLabel(r.overall_score);
 73→  const confLabel = getConfidenceLabel(confidence);
 74→  const rec = getRecommendation(r.overall_score, r.hard_fit);
 75→
 76→  if (totalMustHave === 0 && !r.explanation_json?.why_ranked_here && risks.length === 0) return null;
 77→
 78→  return (
 79→    <div className="rounded-lg border border-border bg-card overflow-hidden">
 80→      {/* ── Header ─────────────────────────────────────────── */}
 81→      <div className="px-4 py-3 border-b border-border bg-muted/30">
 82→        <div className="flex items-center gap-3 flex-wrap">
 83→          <div className="flex items-center gap-2">
 84→            <FileCheck className="h-4 w-4 text-score-jd" />
 85→            <span className="text-xs font-semibold uppercase tracking-wide text-foreground">JD Aligned</span>
 86→          </div>
 87→
 88→          {/* Match score */}
 89→          <div className="flex items-center gap-1.5">
 90→            <span className="text-lg font-bold tabular-nums text-foreground">{r.overall_score?.toFixed(0)}%</span>
 91→            <span className="text-[10px] text-muted-foreground leading-tight">Match<br />score</span>
 92→          </div>
 93→
 94→          <Badge variant="outline" className={`text-[10px] ${matchLabel.cls}`}>{matchLabel.text}</Badge>
 95→          <Badge variant="outline" className={`text-[10px] ${confLabel.cls}`}>{confLabel.text}</Badge>
 96→
 97→          {/* Summary chips */}
 98→          <div className="flex items-center gap-1.5 ml-auto flex-wrap">
 99→            {totalMustHave > 0 && (
100→              <Badge variant="outline" className="text-[10px] bg-emerald-500/10 text-emerald-600 border-emerald-200">
101→                {matched.length}/{totalMustHave} must-have
102→              </Badge>
103→            )}
104→            {totalPreferred > 0 && (
105→              <Badge variant="outline" className="text-[10px] bg-blue-500/10 text-blue-600 border-blue-200">
106→                {matchedPreferred.length}/{totalPreferred} preferred
107→              </Badge>
108→            )}
109→            {missing.length + missingPreferred.length > 0 && (
110→              <Badge variant="outline" className="text-[10px] bg-red-500/10 text-red-600 border-red-200">
111→                {missing.length + missingPreferred.length} not met
112→              </Badge>
113→            )}
114→          </div>
115→        </div>
116→      </div>
117→
118→      {/* ── 4-Column Grid ──────────────────────────────────── */}
119→      <div className="p-4">
120→        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
121→          {/* MUST HAVE */}
122→          <div className="space-y-2">
123→            <span className="text-[10px] uppercase tracking-wider text-emerald-600 font-semibold flex items-center gap-1">
124→              <ShieldCheck className="h-3 w-3" /> Must Have
125→            </span>
126→            <div className="space-y-1.5">
