194→              {rec.text}
195→            </div>
196→
197→            {/* Interview Focus */}
198→            {interviewQs.length > 0 && (
199→              <div className="p-2 rounded bg-purple-500/5 border border-purple-500/20 text-[11px]">
200→                <span className="text-[9px] uppercase tracking-wider font-semibold text-purple-600 block mb-0.5">
201→                  Interview Focus
