210→                {r.explanation_json.key_tradeoffs}
211→              </p>
212→            )}
213→          </div>
214→
215→          {/* RISK SIGNALS */}
216→          <div className="space-y-2">
217→            <span className="text-[10px] uppercase tracking-wider text-destructive font-semibold flex items-center gap-1">
218→              <ShieldAlert className="h-3 w-3" /> Risk Signals
219→            </span>
220→            <div className="space-y-1.5">
221→              {risks.map((risk, i) => (
222→                <div
223→                  key={i}
224→                  className={`text-[11px] px-2.5 py-1.5 rounded-md font-medium border ${
