229→                        : "bg-emerald-500/10 text-emerald-600 border-emerald-200"
230→                  }`}
231→                >
232→                  {risk.text}
233→                </div>
234→              ))}
235→              {risks.length === 0 && <p className="text-xs text-muted-foreground italic">No risk signals</p>}
236→            </div>
237→          </div>
238→        </div>
239→      </div>
240→
241→      {/* ── AI Suggestion Bar ──────────────────────────────── */}
242→      {missing.length + missingPreferred.length > 0 && onRewriteJd && (
243→        <div className="px-4 py-2.5 border-t border-border bg-muted/20 flex items-center gap-3 flex-wrap">
244→          <Lightbulb className="h-3.5 w-3.5 text-amber-500 shrink-0" />
245→          <p className="text-xs text-muted-foreground flex-1">
246→            <span className="font-medium text-foreground">AI suggestion</span>{" "}
247→            Softening{" "}
248→            <span className="font-medium">{missing[0] || missingPreferred[0]}</span>{" "}
249→            requirements may surface more qualified candidates for this role
250→          </p>
251→          <Button
252→            variant="outline"
253→            size="sm"
254→            className="h-7 text-xs gap-1.5 shrink-0"
255→            onClick={(e) => {
256→              e.stopPropagation();
257→              onRewriteJd();
258→            }}
259→          >
260→            <Wand2 className="h-3 w-3" />
261→            Rewrite JD
262→          </Button>
263→        </div>
264→      )}
265→    </div>
266→  );
267→};
268→
269→export default JDAlignedPanel;
