import { CheckCircle2, XCircle } from "lucide-react";
import type { Result } from "@/pages/Index";

interface StrengthsGapsPanelProps {
  result: Result;
}

const StrengthsGapsPanel = ({ result: r }: StrengthsGapsPanelProps) => {
  const strengths = (r.strengths_json || r.matched_must_haves || []) as string[];
  const gaps = (r.gaps_json || r.missing_must_haves || r.missing_skills || []) as string[];

  if (strengths.length === 0 && gaps.length === 0) return null;

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {/* Strengths */}
      {strengths.length > 0 && (
        <div className="space-y-2">
          <h5 className="text-xs font-semibold text-success uppercase tracking-wide flex items-center gap-1">
            <CheckCircle2 className="h-3.5 w-3.5" /> Strengths
          </h5>
          <div className="space-y-1.5">
            {strengths.slice(0, 6).map((s, i) => (
              <div key={i} className="flex items-center gap-2 text-xs px-2.5 py-1.5 rounded-md bg-success/5 border border-success/15 text-foreground">
                <CheckCircle2 className="h-3 w-3 text-success shrink-0" />
                {s}
              </div>
            ))}
          </div>
        </div>
      )}
      {/* Gaps */}
      {gaps.length > 0 && (
        <div className="space-y-2">
          <h5 className="text-xs font-semibold text-destructive uppercase tracking-wide flex items-center gap-1">
            <XCircle className="h-3.5 w-3.5" /> Gaps
          </h5>
          <div className="space-y-1.5">
            {gaps.slice(0, 6).map((g, i) => (
              <div key={i} className="flex items-center gap-2 text-xs px-2.5 py-1.5 rounded-md bg-destructive/5 border border-destructive/15 text-foreground">
                <XCircle className="h-3 w-3 text-destructive shrink-0" />
                {g}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default StrengthsGapsPanel;

