import { Badge } from "@/components/ui/badge";
import { GraduationCap } from "lucide-react";

interface Education {
  degree?: string;
  institution?: string;
  year?: string;
}

interface EducationPanelProps {
  parsedJson: any;
  matchedMustHaves?: string[];
  missingMustHaves?: string[];
}

const EducationPanel = ({ parsedJson, matchedMustHaves, missingMustHaves }: EducationPanelProps) => {
  const education: Education[] = parsedJson?.education || [];
  const certifications: string[] = parsedJson?.certifications || [];
  const matchedLower = (matchedMustHaves || []).map((m: string) => m.toLowerCase());
  const missingLower = (missingMustHaves || []).map((m: string) => m.toLowerCase());

  const getRelevanceChip = (degree: string, institution: string) => {
    const combined = `${degree} ${institution}`.toLowerCase();

    // Check if this education matches a specific must-have requirement
    const isMatched = matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.some((w) => combined.includes(w));
    });
    if (isMatched) return { label: "JD Match", color: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };

    // Check if this education is a gap (missing requirement related to education)
    const isGap = missingLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.some((w) => combined.includes(w));
    });
    if (isGap) return { label: "Gap", color: "bg-red-500/10 text-red-600 border-red-200" };

    if (degree) return { label: "Relevant", color: "bg-blue-500/10 text-blue-600 border-blue-200" };
    return null;
  };

  const matchCount = education.filter((e) => {
    const chip = getRelevanceChip(e.degree || "", e.institution || "");
    return chip?.label === "JD Match";
  }).length;

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Education</h4>
        {matchCount > 0 && (
          <Badge variant="outline" className="ml-auto text-[10px]">{matchCount} matched</Badge>
        )}
      </div>

      {education.length > 0 ? (
        <div className="space-y-3">
          {education.slice(0, 4).map((edu, i) => {
            const chip = getRelevanceChip(edu.degree || "", edu.institution || "");
            return (
              <div key={i} className="space-y-0.5">
                <div className="flex items-start gap-1.5">
                  <GraduationCap className="h-3 w-3 text-muted-foreground shrink-0 mt-0.5" />
                  <div className="min-w-0">
                    <p className="text-xs font-medium text-foreground leading-tight">{edu.degree || "Degree"}</p>
                    {edu.institution && (
                      <p className="text-[11px] text-muted-foreground truncate">{edu.institution}</p>
                    )}
                    <div className="flex items-center gap-1.5 mt-0.5">
                      {edu.year && <span className="text-[10px] text-muted-foreground">{edu.year}</span>}
                      {chip && (
                        <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${chip.color}`}>
                          {chip.label}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No education data available</p>
      )}

      {certifications.length > 0 && (
        <div className="pt-1 space-y-1">
          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Certifications</span>
          <div className="flex flex-wrap gap-1">
            {certifications.slice(0, 4).map((cert, i) => (
              <Badge key={i} variant="outline" className="text-[10px]">{cert}</Badge>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default EducationPanel;

