      expect(risks.some((r) => r.text === "Missing critical requirements" && r.v === "red")).toBe(true);
    });

    it("should NOT show missing critical when hard_fit false but no missing items", () => {
      const risks = deriveRisks(["React"], [], 60, false, false);
      expect(risks.some((r) => r.text === "Missing critical requirements")).toBe(false);
    });

    it("should order: positives first, warnings, negatives last", () => {
      const risks = deriveRisks(["React", "Node"], ["Docker"], 55, false, true);
      // All met (green) → medium confidence (amber) → heuristic (amber) → missing critical (red)
      const severities = risks.map((r) => r.v);
      const greenIdx = severities.indexOf("green");
      const lastAmberIdx = severities.lastIndexOf("amber");
      const redIdx = severities.indexOf("red");
      if (greenIdx >= 0 && lastAmberIdx >= 0) expect(greenIdx).toBeLessThan(lastAmberIdx);
      if (lastAmberIdx >= 0 && redIdx >= 0) expect(lastAmberIdx).toBeLessThan(redIdx);
    });

    it("should return empty array when confidence is 0 and no must-haves", () => {
      const risks = deriveRisks([], [], 0, undefined, false);
      expect(risks).toEqual([]);
    });
  });

  describe("must-have percentage calculation", () => {
    it("should calculate 100% when all matched", () => {
      const matched = ["React", "Node", "TypeScript"];
      const missing: string[] = [];
      const total = matched.length + missing.length;
      const pct = total > 0 ? Math.round((matched.length / total) * 100) : 0;
      expect(pct).toBe(100);
    });

    it("should calculate 0% when none matched", () => {
      const matched: string[] = [];
      const missing = ["React", "Node"];
      const total = matched.length + missing.length;
      const pct = total > 0 ? Math.round((matched.length / total) * 100) : 0;
      expect(pct).toBe(0);
    });

    it("should calculate 67% for 2 of 3", () => {
      const matched = ["React", "Node"];
      const missing = ["Docker"];
      const total = matched.length + missing.length;
      const pct = total > 0 ? Math.round((matched.length / total) * 100) : 0;
      expect(pct).toBe(67);
    });

    it("should return 0 when both arrays are empty", () => {
      const total = 0;
      const pct = total > 0 ? Math.round((0 / total) * 100) : 0;
      expect(pct).toBe(0);
    });
  });
});

