    it("should give higher score when JD matches exist", () => {
      // 3 useful out of 4 total, with 1 JD match
      const withMatch = Math.round((3 / 4) * 90 + 10); // 77.5 → 78
      const withoutMatch = Math.round((3 / 4) * 65); // 48.75 → 49
