import { describe, it, expect } from "vitest";

/**
 * Tests for EducationPanel logic — level inference, year pills,
 * relevance tagging, match score, and gap detection.
 */

/* ── Replicated logic from EducationPanel.tsx ─────────────── */

type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";

const inferLevel = (degree: string): EduLevel => {
  const d = degree.toLowerCase();
  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
  if (d.includes("bachelor") || d.includes("b.sc") || d.includes("b.tech") || d.includes("b.e.") || d.includes("b.a.") || d.includes("bsc") || d.includes("b.com") || d.includes("bba") || d.includes("bca")) return "bachelors";
  if (d.includes("diploma") || d.includes("certificate") || d.includes("pgd") || d.includes("post graduate diploma")) return "diploma";
  if (d.includes("higher secondary") || d.includes("12th") || d.includes("hsc") || d.includes("intermediate") || d.includes("a-level") || d.includes("senior secondary")) return "higher_secondary";
  if (d.includes("secondary") || d.includes("10th") || d.includes("ssc") || d.includes("o-level") || d.includes("high school") || d.includes("matriculation")) return "secondary";
  return "other";
};

const isLowRelevance = (level: EduLevel): boolean =>
  level === "secondary" || level === "higher_secondary";

const extractYear = (yearStr?: string): number | null => {
  if (!yearStr) return null;
  const match = yearStr.match(/\b(19|20)\d{2}\b/g);
  if (!match) return null;
  return Math.max(...match.map(Number));
};

const getYearAge = (year: number): "recent" | "old" | "normal" => {
  const age = new Date().getFullYear() - year;
  if (age <= 3) return "recent";
  if (age >= 5) return "old";
  return "normal";
};

type RelevanceTag = "jd_match" | "relevant" | "gap" | "low_relevance";

function classifyEducation(
  degree: string,
  institution: string,
  matchedLower: string[],
  level: EduLevel
): RelevanceTag {
  const combined = `${degree} ${institution}`.toLowerCase();
  const isMatched = matchedLower.some((m) => {
    const words = m.split(/\s+/).filter((w) => w.length > 3);
    return words.some((w) => combined.includes(w));
  });
  if (isMatched) return "jd_match";
  return isLowRelevance(level) ? "low_relevance" : "relevant";
}

/* ── Tests ─────────────────────────────────────────────────── */

describe("EducationPanel logic", () => {
  describe("inferLevel", () => {
    it("should detect PhD / Doctorate", () => {
      expect(inferLevel("PhD in Computer Science")).toBe("doctorate");
      expect(inferLevel("Doctorate in Physics")).toBe("doctorate");
      expect(inferLevel("D.Phil Mathematics")).toBe("doctorate");
    });

    it("should detect Masters degrees", () => {
      expect(inferLevel("Master of Science")).toBe("masters");
      expect(inferLevel("MBA")).toBe("masters");
      expect(inferLevel("M.Sc in Data Science")).toBe("masters");
      expect(inferLevel("M.Tech Computer Science")).toBe("masters");
      expect(inferLevel("MSc Physics")).toBe("masters");
      expect(inferLevel("M.Com")).toBe("masters");
    });

    it("should detect Bachelors degrees", () => {
      expect(inferLevel("Bachelor of Science")).toBe("bachelors");
      expect(inferLevel("B.Sc Computer Science")).toBe("bachelors");
      expect(inferLevel("B.Tech IT")).toBe("bachelors");
      expect(inferLevel("B.E. Mechanical")).toBe("bachelors");
      expect(inferLevel("BBA")).toBe("bachelors");
      expect(inferLevel("BCA")).toBe("bachelors");
      expect(inferLevel("B.Com")).toBe("bachelors");
    });

    it("should detect Diploma / Certificate", () => {
      expect(inferLevel("Diploma in UI/UX Design")).toBe("diploma");
      expect(inferLevel("Certificate in Web Development")).toBe("diploma");
      expect(inferLevel("PGD in Marketing")).toBe("diploma");
      expect(inferLevel("Post Graduate Diploma in Management")).toBe("diploma");
    });

    it("should detect Higher Secondary", () => {
      expect(inferLevel("Higher Secondary - Science")).toBe("higher_secondary");
      expect(inferLevel("12th Grade")).toBe("higher_secondary");
      expect(inferLevel("HSC")).toBe("higher_secondary");
      expect(inferLevel("Intermediate")).toBe("higher_secondary");
      expect(inferLevel("A-Level")).toBe("higher_secondary");
      expect(inferLevel("Senior Secondary")).toBe("higher_secondary");
    });

    it("should detect Secondary", () => {
      expect(inferLevel("Secondary")).toBe("secondary");
      expect(inferLevel("10th Grade")).toBe("secondary");
      expect(inferLevel("SSC")).toBe("secondary");
      expect(inferLevel("O-Level")).toBe("secondary");
      expect(inferLevel("High School Diploma")).toBe("secondary");
      expect(inferLevel("Matriculation")).toBe("secondary");
    });

    it("should return other for unrecognized degrees", () => {
      expect(inferLevel("Some Random Program")).toBe("other");
      expect(inferLevel("")).toBe("other");
    });

    it("should be case-insensitive", () => {
      expect(inferLevel("PHD IN SCIENCE")).toBe("doctorate");
      expect(inferLevel("master of arts")).toBe("masters");
      expect(inferLevel("BACHELOR OF ENGINEERING")).toBe("bachelors");
    });
  });

  describe("isLowRelevance", () => {
    it("should return true for secondary and higher_secondary", () => {
      expect(isLowRelevance("secondary")).toBe(true);
      expect(isLowRelevance("higher_secondary")).toBe(true);
    });

    it("should return false for higher education levels", () => {
      expect(isLowRelevance("doctorate")).toBe(false);
      expect(isLowRelevance("masters")).toBe(false);
      expect(isLowRelevance("bachelors")).toBe(false);
      expect(isLowRelevance("diploma")).toBe(false);
      expect(isLowRelevance("other")).toBe(false);
    });
  });

  describe("extractYear", () => {
    it("should extract a 4-digit year from simple string", () => {
      expect(extractYear("2021")).toBe(2021);
    });

    it("should extract the latest year from a range", () => {
      expect(extractYear("Jun 2017 - Oct 2020")).toBe(2020);
      expect(extractYear("2015 - 2019")).toBe(2019);
    });

    it("should extract year from mixed text", () => {
      expect(extractYear("Graduated in 2023")).toBe(2023);
    });

    it("should return null for empty/undefined input", () => {
      expect(extractYear("")).toBeNull();
      expect(extractYear(undefined)).toBeNull();
    });

    it("should return null for strings with no year", () => {
      expect(extractYear("Present")).toBeNull();
      expect(extractYear("N/A")).toBeNull();
    });

    it("should handle year at boundary (1900s and 2000s)", () => {
      expect(extractYear("1999")).toBe(1999);
      expect(extractYear("2000")).toBe(2000);
    });
  });

  describe("getYearAge", () => {
    const currentYear = new Date().getFullYear();

    it("should return recent for years within last 3 years", () => {
      expect(getYearAge(currentYear)).toBe("recent");
      expect(getYearAge(currentYear - 1)).toBe("recent");
      expect(getYearAge(currentYear - 3)).toBe("recent");
    });

    it("should return old for years 5+ years ago", () => {
      expect(getYearAge(currentYear - 5)).toBe("old");
      expect(getYearAge(currentYear - 10)).toBe("old");
      expect(getYearAge(2015)).toBe("old");
    });

    it("should return normal for years 4 years ago", () => {
      expect(getYearAge(currentYear - 4)).toBe("normal");
    });
  });

  describe("classifyEducation", () => {
    it("should return jd_match when degree matches a must-have", () => {
      const tag = classifyEducation(
        "Diploma in UI/UX Design",
        "Edit Institute",
        ["ui/ux design experience"],
        "diploma"
      );
      expect(tag).toBe("jd_match");
    });

    it("should return relevant for bachelors not matching must-haves", () => {
      const tag = classifyEducation(
        "Bachelor of Science in Physics",
        "MIT",
        ["react experience"],
        "bachelors"
      );
      expect(tag).toBe("relevant");
    });

    it("should return low_relevance for secondary education", () => {
      const tag = classifyEducation(
        "Secondary",
        "Local School",
        [],
        "secondary"
      );
      expect(tag).toBe("low_relevance");
    });

    it("should return low_relevance for higher_secondary", () => {
      const tag = classifyEducation(
        "Higher Secondary - Science",
        "City College",
        [],
        "higher_secondary"
      );
      expect(tag).toBe("low_relevance");
    });

    it("should prioritize jd_match over low_relevance", () => {
      // Even for secondary, if it somehow matches a must-have, it should be jd_match
      const tag = classifyEducation(
        "High School Diploma in Design",
        "Design School",
        ["design experience"],
        "secondary"
      );
      expect(tag).toBe("jd_match");
    });

    it("should handle empty must-haves array", () => {
      const tag = classifyEducation("BSc Computer Science", "University", [], "bachelors");
      expect(tag).toBe("relevant");
    });

    it("should ignore short words (≤3 chars) when matching", () => {
      // "in" and "IT" have length ≤ 3, should be ignored
      const tag = classifyEducation(
        "Diploma in Arts",
        "City College",
        ["in it"],
        "diploma"
      );
      // No words longer than 3 chars in the must-have, so no match
      expect(tag).toBe("relevant");
    });
  });

  describe("education gap detection", () => {
    const educationKeywords = ["degree", "education", "qualification", "certified", "certificate", "diploma", "bachelor", "master", "phd", "analytics", "marketing", "design", "engineering", "computer", "science", "mba"];

    function detectEducationGaps(missingMustHaves: string[]): string[] {
      return missingMustHaves.filter((m) =>
        educationKeywords.some((k) => m.toLowerCase().includes(k))
      );
    }

    it("should detect education-related gaps", () => {
      const gaps = detectEducationGaps([
        "No formal CRO / Marketing education",
        "5 years of React experience",
        "Data analytics qualification",
      ]);
      expect(gaps).toContain("No formal CRO / Marketing education");
      expect(gaps).toContain("Data analytics qualification");
      expect(gaps).not.toContain("5 years of React experience");
    });

    it("should return empty for non-education gaps", () => {
      const gaps = detectEducationGaps([
        "Docker experience",
        "Kubernetes knowledge",
        "Team leadership",
      ]);
      expect(gaps).toEqual([]);
    });

    it("should handle empty array", () => {
      expect(detectEducationGaps([])).toEqual([]);
    });

    it("should be case-insensitive", () => {
      const gaps = detectEducationGaps(["MASTER'S DEGREE required"]);
      expect(gaps.length).toBe(1);
    });
  });

  describe("match score calculation", () => {
    it("should give higher score when JD matches exist", () => {
      // 3 useful out of 4 total, with 1 JD match
      const withMatch = Math.round((3 / 4) * 90 + 10); // 77.5 → 78
      const withoutMatch = Math.round((3 / 4) * 65); // 48.75 → 49
      expect(withMatch).toBeGreaterThan(withoutMatch);
    });

    it("should return 0 for empty education", () => {
      const score = 0; // classified.length === 0
      expect(score).toBe(0);
    });

    it("should max out near 100 for all useful with JD match", () => {
      // 4 useful out of 4 total, with JD match
      const score = Math.round((4 / 4) * 90 + 10);
      expect(score).toBe(100);
    });
  });
});

