import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { GraduationCap, BookOpen, School, Award, ChevronDown, ChevronUp, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";

interface Education {
  degree?: string;
  institution?: string;
  year?: string;
}

interface EducationPanelProps {
  parsedJson: any;
  matchedMustHaves?: string[];
  missingMustHaves?: string[];
}

/* ── Helpers ──────────────────────────────────────────────── */

/** Extract the most recent 4-digit year from a date string */
const extractYear = (yearStr?: string): number | null => {
  if (!yearStr) return null;
  const match = yearStr.match(/\b(19|20)\d{2}\b/g);
  if (!match) return null;
  return Math.max(...match.map(Number));
};

/** Year pill colour: green if recent (≤3 yrs), amber if old (5+ yrs), grey otherwise */
const getYearVariant = (year: number): { cls: string } => {
  const age = new Date().getFullYear() - year;
  if (age <= 3) return { cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (age >= 5) return { cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  return { cls: "bg-muted text-muted-foreground border-border" };
};

/** Infer education level from degree name for icon + rank */
type EduLevel = "doctorate" | "masters" | "bachelors" | "diploma" | "higher_secondary" | "secondary" | "other";

const inferLevel = (degree: string): EduLevel => {
  const d = degree.toLowerCase();
  if (d.includes("phd") || d.includes("doctorate") || d.includes("d.phil")) return "doctorate";
  if (d.includes("master") || d.includes("mba") || d.includes("m.sc") || d.includes("m.tech") || d.includes("m.e.") || d.includes("m.a.") || d.includes("msc") || d.includes("m.com")) return "masters";
  if (d.includes("bachelor") || d.includes("b.sc") || d.includes("b.tech") || d.includes("b.e.") || d.includes("b.a.") || d.includes("bsc") || d.includes("b.com") || d.includes("bba") || d.includes("bca")) return "bachelors";
  // Check secondary/higher_secondary BEFORE diploma — "High School Diploma" should be secondary, not diploma
  if (d.includes("higher secondary") || d.includes("12th") || d.includes("hsc") || d.includes("intermediate") || d.includes("a-level") || d.includes("senior secondary")) return "higher_secondary";
  if (d.includes("secondary") || d.includes("10th") || d.includes("ssc") || d.includes("o-level") || d.includes("high school") || d.includes("matriculation")) return "secondary";
  if (d.includes("diploma") || d.includes("certificate") || d.includes("pgd") || d.includes("post graduate diploma")) return "diploma";
  return "other";
};

const LEVEL_ICON: Record<EduLevel, typeof GraduationCap> = {
  doctorate: Award,
  masters: GraduationCap,
  bachelors: BookOpen,
  diploma: School,
  higher_secondary: School,
  secondary: School,
  other: GraduationCap,
};

const LEVEL_RANK: Record<EduLevel, { label: string; cls: string }> = {
  doctorate: { label: "Research", cls: "bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800" },
  masters: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  bachelors: { label: "Ranked", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" },
  diploma: { label: "Specialised", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  higher_secondary: { label: "Tier 2", cls: "bg-muted text-muted-foreground border-border" },
  secondary: { label: "Secondary", cls: "bg-muted text-muted-foreground border-border" },
  other: { label: "Other", cls: "bg-muted text-muted-foreground border-border" },
};

/** Is this a low-relevance qualification? (secondary school etc.) */
const isLowRelevance = (level: EduLevel): boolean =>
  level === "secondary" || level === "higher_secondary";

/** Match score label */
const getScoreLabel = (score: number): { text: string; cls: string } => {
  if (score >= 75) return { text: "Strong", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (score >= 50) return { text: "Good", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
  if (score >= 25) return { text: "Partial", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  return { text: "Weak", cls: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800" };
};

type RelevanceTag = "jd_match" | "relevant" | "gap" | "low_relevance";
const RELEVANCE_CLS: Record<RelevanceTag, string> = {
  jd_match: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800",
  relevant: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800",
  gap: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800",
  low_relevance: "bg-muted/60 text-muted-foreground border-border",
};
const RELEVANCE_LABEL: Record<RelevanceTag, string> = {
  jd_match: "JD Match",
  relevant: "Relevant",
  gap: "Gap",
  low_relevance: "Low relevance",
};

/* ── Component ────────────────────────────────────────────── */

const EducationPanel = ({ parsedJson, matchedMustHaves, missingMustHaves }: EducationPanelProps) => {
  const [showDetail, setShowDetail] = useState(false);
  const education: Education[] = parsedJson?.education || [];
  const certifications: string[] = parsedJson?.certifications || [];
  const matchedLower = (matchedMustHaves || []).map((m: string) => m.toLowerCase());
  const missingLower = (missingMustHaves || []).map((m: string) => m.toLowerCase());

  // Classify each education entry
  const classified = education.map((edu) => {
    const degree = edu.degree || "";
    const institution = edu.institution || "";
    const combined = `${degree} ${institution}`.toLowerCase();
    const level = inferLevel(degree);
    const year = extractYear(edu.year);
    const Icon = LEVEL_ICON[level];
    const rank = LEVEL_RANK[level];

    let tag: RelevanceTag = isLowRelevance(level) ? "low_relevance" : "relevant";
    const isMatched = matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.some((w) => combined.includes(w));
    });
    if (isMatched) tag = "jd_match";

    return { ...edu, degree, institution, level, year, Icon, rank, tag };
  });

  // Stats
  const jdMatchCount = classified.filter((c) => c.tag === "jd_match").length;
  const relevantCount = classified.filter((c) => c.tag === "relevant").length;
  const useful = classified.filter((c) => c.tag !== "low_relevance");

  // Education gaps — missing must-haves related to education
  const educationKeywords = ["degree", "education", "qualification", "certified", "certificate", "diploma", "bachelor", "master", "phd", "analytics", "marketing", "design", "engineering", "computer", "science", "mba"];
  const educationGaps = missingLower
    .filter((m) => educationKeywords.some((k) => m.includes(k)) || m.includes("formal"))
    .map((m) => {
      const original = (missingMustHaves || []).find((o) => o.toLowerCase() === m) || m;
      const isCritical = matchedLower.length > 0 || missingLower.indexOf(m) < missingLower.length / 2;
      return { text: original, severity: isCritical ? "critical" as const : "preferred" as const };
    });
  const gapCount = educationGaps.length;

  // Match score: percentage of useful qualifications vs total, weighted by relevance
  const matchScore = classified.length > 0
    ? Math.round((useful.length / classified.length) * (jdMatchCount > 0 ? 90 : 65) + (jdMatchCount > 0 ? 10 : 0))
    : 0;
  const scoreLabel = getScoreLabel(matchScore);

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      {/* ── Header with stat pills ─────────────────────────── */}
      <div className="flex items-center gap-2 flex-wrap">
        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Education</h4>
        <div className="flex items-center gap-1 ml-auto flex-wrap">
          {jdMatchCount > 0 && (
            <Badge variant="outline" className={`text-[9px] ${RELEVANCE_CLS.jd_match}`}>
              {jdMatchCount} JD Match
            </Badge>
          )}
          {relevantCount > 0 && (
            <Badge variant="outline" className={`text-[9px] ${RELEVANCE_CLS.relevant}`}>
              {relevantCount} Relevant
            </Badge>
          )}
          {gapCount > 0 && (
            <Badge variant="outline" className={`text-[9px] ${RELEVANCE_CLS.gap}`}>
              {gapCount} Gap
            </Badge>
          )}
        </div>
      </div>

      {/* ── Match score bar ────────────────────────────────── */}
      {classified.length > 0 && (
        <div className="space-y-1.5">
          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Education Match Score</span>
          <div className="flex items-center gap-3">
            <span className="text-xl font-bold tabular-nums text-foreground">{matchScore}%</span>
            <div className="flex-1 space-y-1">
              <div className="flex items-center gap-1.5">
                <Badge variant="outline" className={`text-[9px] ${scoreLabel.cls}`}>{scoreLabel.text}</Badge>
                <span className="text-[9px] text-muted-foreground">AI estimated · {useful.length} of {classified.length} useful</span>
              </div>
              <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                <div
                  className="h-full rounded-full bg-score-education transition-all"
                  style={{ width: `${Math.min(matchScore, 100)}%` }}
                />
              </div>
              <div className="flex justify-between text-[8px] text-muted-foreground/50">
                <span>Weak</span><span>Partial</span><span>Good</span><span>Strong</span>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ── Qualifications list ────────────────────────────── */}
      {classified.length > 0 ? (
        <div className="space-y-1">
          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Qualifications</span>
          <div className="space-y-2">
            {classified.slice(0, 4).map((edu, i) => {
              const lowRel = edu.tag === "low_relevance";
              return (
                <div key={i} className={`flex items-start gap-2 ${lowRel ? "opacity-40" : ""}`}>
                  <edu.Icon className={`h-3.5 w-3.5 shrink-0 mt-0.5 ${lowRel ? "text-muted-foreground/60" : "text-muted-foreground"}`} />
                  <div className="flex-1 min-w-0 space-y-0.5">
                    <p className={`text-xs font-medium leading-tight ${lowRel ? "text-muted-foreground" : "text-foreground"}`}>
                      {edu.degree || "Degree"}
                    </p>
                    {edu.institution && (
                      <p className="text-[11px] text-muted-foreground">{edu.institution}</p>
                    )}
                    <div className="flex items-center gap-1.5 flex-wrap">
                      {edu.year && edu.year !== "" && (() => {
                        const yearNum = edu.year ? extractYear(edu.year) : null;
                        const yearVariant = yearNum ? getYearVariant(yearNum) : null;
                        return (
                          <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${yearVariant?.cls || "bg-muted text-muted-foreground border-border"}`}>
                            {yearNum || edu.year}
                          </span>
                        );
                      })()}
                      {!lowRel && (
                        <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${edu.rank.cls}`}>
                          {edu.rank.label}
                        </span>
                      )}
                    </div>
                  </div>
                  <Badge variant="outline" className={`text-[9px] shrink-0 mt-0.5 ${RELEVANCE_CLS[edu.tag]}`}>
                    {RELEVANCE_LABEL[edu.tag]}
                  </Badge>
                </div>
              );
            })}
            {classified.length > 4 && (
              <p className="text-[10px] text-muted-foreground">+{classified.length - 4} more</p>
            )}
          </div>
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No education data available</p>
      )}

      {/* ── Gaps — Hiring Risk ─────────────────────────────── */}
      {educationGaps.length > 0 && (
        <div className="space-y-1.5">
          <span className="text-[10px] uppercase tracking-wider text-destructive font-medium flex items-center gap-1">
            <AlertTriangle className="h-3 w-3" /> Gaps — Hiring Risk
          </span>
          <div className="space-y-1.5">
            {educationGaps.map((gap, i) => (
              <div
                key={i}
                className={`text-[11px] px-2.5 py-1.5 rounded-md border flex items-center justify-between gap-2 ${
                  gap.severity === "critical"
                    ? "bg-red-500/10 text-red-700 border-red-200 dark:text-red-400 dark:border-red-800"
                    : "bg-amber-500/10 text-amber-700 border-amber-200 dark:text-amber-400 dark:border-amber-800"
                }`}
              >
                <span className="font-medium">{gap.text}</span>
                <Badge variant="outline" className={`text-[8px] shrink-0 uppercase ${
                  gap.severity === "critical"
