const JDAlignedPanel = ({ result: r, onRewriteJd }: JDAlignedPanelProps) => {
  const matched = (r.matched_must_haves as string[]) || [];
  const missing = (r.missing_must_haves as string[]) || [];
  const strengths = (r.strengths_json || []) as string[];
  const gaps = (r.gaps_json || []) as string[];
  const confidence = r.confidence ?? 0;
  const interviewQs = Array.isArray(r.interview_questions) ? (r.interview_questions as string[]) : [];
  const isHeuristic = r.scoring_version === "heuristic";
  const isInsufficient = r.scoring_version === "insufficient";

  // Don't render for insufficient data — nothing meaningful to show
  if (isInsufficient) return null;

  // Must-have stats
