            <FileCheck className="h-4 w-4 text-score-jd" />
            <span className="text-xs font-semibold uppercase tracking-wide text-foreground">JD Aligned</span>
          </div>

          {/* Must-have match percentage — the real JD alignment metric */}
          {totalMustHave > 0 && (
            <div className="flex items-center gap-1.5">
              <span className="text-lg font-bold tabular-nums text-foreground">{mustHavePercent}%</span>
              <span className="text-[10px] text-muted-foreground leading-tight">Must-have<br />match</span>
            </div>
          )}

          <Badge variant="outline" className={`text-[10px] ${VARIANT_CLS[matchLabel.v]}`}>{matchLabel.text}</Badge>
          <Badge variant="outline" className={`text-[10px] ${VARIANT_CLS[confLabel.v]}`}>{confLabel.text}</Badge>

          {/* Summary chips */}
          <div className="flex items-center gap-1.5 ml-auto flex-wrap">
            {totalMustHave > 0 && (
              <Badge variant="outline" className={`text-[10px] ${VARIANT_CLS.green}`}>
                {matched.length}/{totalMustHave} must-have
              </Badge>
            )}
            {totalPreferred > 0 && (
              <Badge variant="outline" className={`text-[10px] ${VARIANT_CLS.blue}`}>
                {matchedPreferred.length}/{totalPreferred} preferred
              </Badge>
            )}
            {missing.length + missingPreferred.length > 0 && (
              <Badge variant="outline" className={`text-[10px] ${VARIANT_CLS.red}`}>
                {missing.length + missingPreferred.length} not met
              </Badge>
            )}
          </div>
        </div>
      </div>

      {/* ── 4-Column Grid ──────────────────────────────────── */}
      <div className="p-4">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {/* MUST HAVE */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-emerald-600 dark:text-emerald-400 font-semibold flex items-center gap-1">
              <ShieldCheck className="h-3 w-3" /> Must Have
            </span>
            <div className="space-y-1.5">
              {matched.map((item, i) => (
                <div key={`m-${i}`} className="flex items-start gap-1.5 text-xs">
                  <CheckCircle2 className="h-3.5 w-3.5 text-emerald-500 shrink-0 mt-0.5" />
                  <span className="text-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className={`text-[9px] shrink-0 ${VARIANT_CLS.green}`}>Met</Badge>
                </div>
              ))}
              {missing.map((item, i) => (
                <div key={`x-${i}`} className="flex items-start gap-1.5 text-xs">
                  <XCircle className="h-3.5 w-3.5 text-destructive shrink-0 mt-0.5" />
                  <span className="text-muted-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className={`text-[9px] shrink-0 ${VARIANT_CLS.red}`}>Not Met</Badge>
                </div>
              ))}
              {totalMustHave === 0 && (
                <p className="text-xs text-muted-foreground italic">No must-have data</p>
              )}
            </div>
          </div>

          {/* PREFERRED */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-blue-600 dark:text-blue-400 font-semibold flex items-center gap-1">
              <Target className="h-3 w-3" /> Preferred
            </span>
            <div className="space-y-1.5">
              {matchedPreferred.map((item, i) => (
                <div key={`pm-${i}`} className="flex items-start gap-1.5 text-xs">
                  <CheckCircle2 className="h-3.5 w-3.5 text-blue-500 shrink-0 mt-0.5" />
                  <span className="text-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className={`text-[9px] shrink-0 ${VARIANT_CLS.blue}`}>Met</Badge>
                </div>
              ))}
              {missingPreferred.map((item, i) => (
                <div key={`px-${i}`} className="flex items-start gap-1.5 text-xs">
                  <AlertCircle className="h-3.5 w-3.5 text-amber-500 shrink-0 mt-0.5" />
                  <span className="text-muted-foreground flex-1 leading-snug">{item}</span>
                  <Badge variant="outline" className={`text-[9px] shrink-0 ${VARIANT_CLS.amber}`}>Not Met</Badge>
                </div>
              ))}
              {matchedPreferred.length === 0 && missingPreferred.length === 0 && (
                <p className="text-xs text-muted-foreground italic">No preferred data</p>
              )}
            </div>
          </div>

          {/* AI INSIGHT */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-score-overall font-semibold flex items-center gap-1">
              <Lightbulb className="h-3 w-3" /> AI Insight
            </span>

            {r.explanation_json?.why_ranked_here && (
              <p className="text-[11px] text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
            )}

            {/* Recommendation */}
            <div className={`p-2 rounded text-[11px] font-medium border ${PILL_CLS[rec.v]}`}>
              <span className="text-[9px] uppercase tracking-wider font-semibold block mb-0.5 opacity-70">Recommendation</span>
              {rec.text}
            </div>

            {/* Interview Focus */}
            {interviewQs.length > 0 && (
              <div className="p-2 rounded bg-purple-500/5 border border-purple-500/20 dark:border-purple-500/30 text-[11px]">
                <span className="text-[9px] uppercase tracking-wider font-semibold text-purple-600 dark:text-purple-400 block mb-0.5">
                  Interview Focus
                </span>
                <span className="text-muted-foreground leading-relaxed">{interviewQs[0]}</span>
              </div>
            )}

            {/* Key trade-offs */}
            {r.explanation_json?.key_tradeoffs && (
              <p className="text-[10px] text-muted-foreground leading-relaxed italic">
                {r.explanation_json.key_tradeoffs}
              </p>
            )}
          </div>

          {/* RISK SIGNALS */}
          <div className="space-y-2">
            <span className="text-[10px] uppercase tracking-wider text-destructive font-semibold flex items-center gap-1">
              <ShieldAlert className="h-3 w-3" /> Risk Signals
            </span>
            <div className="space-y-1.5">
              {risks.map((risk, i) => (
                <div key={i} className={`text-[11px] px-2.5 py-1.5 rounded-md font-medium border ${PILL_CLS[risk.v]}`}>
                  {risk.text}
                </div>
              ))}
              {risks.length === 0 && <p className="text-xs text-muted-foreground italic">No risk signals</p>}
            </div>
          </div>
        </div>
      </div>

      {/* ── AI Suggestion Bar ──────────────────────────────── */}
      {missing.length + missingPreferred.length > 0 && onRewriteJd && (
        <div className="px-4 py-2.5 border-t border-border bg-muted/20 flex items-center gap-3 flex-wrap">
          <Lightbulb className="h-3.5 w-3.5 text-amber-500 shrink-0" />
          <p className="text-xs text-muted-foreground flex-1">
            <span className="font-medium text-foreground">AI suggestion</span>{" "}
            Softening{" "}
            <span className="font-medium">{missing[0] || missingPreferred[0]}</span>{" "}
            requirements may surface more qualified candidates for this role
          </p>
          <Button
            variant="outline"
            size="sm"
            className="h-7 text-xs gap-1.5 shrink-0"
            onClick={(e) => {
              e.stopPropagation();
              onRewriteJd();
            }}
          >
            <Wand2 className="h-3 w-3" />
            Rewrite JD
          </Button>
        </div>
      )}
    </div>
  );
};

export default JDAlignedPanel;

