import { Badge } from "@/components/ui/badge";
import { Cpu } from "lucide-react";
import type { Result } from "@/pages/Index";

interface SkillsDetailPanelProps {
  result: Result;
}

const getSkillLevel = (score: number): { label: string; color: string } => {
  if (score >= 90) return { label: "Expert", color: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
  if (score >= 70) return { label: "Adv", color: "bg-blue-500/10 text-blue-600 border-blue-200" };
  if (score >= 50) return { label: "Mid", color: "bg-yellow-500/10 text-yellow-700 border-yellow-200" };
  if (score >= 25) return { label: "Low", color: "bg-orange-500/10 text-orange-600 border-orange-200" };
  return { label: "Gap", color: "bg-red-500/10 text-red-600 border-red-200" };
};

const SkillsDetailPanel = ({ result: r }: SkillsDetailPanelProps) => {
  const scores = r.category_scores_json;
  const skillCount = scores ? Object.keys(scores).length : 0;

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <div className="w-6 h-6 rounded bg-score-skills/10 flex items-center justify-center">
          <Cpu className="h-3.5 w-3.5 text-score-skills" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Skills Detail</h4>
        {skillCount > 0 && (
          <Badge variant="outline" className="ml-auto text-[10px]">{skillCount} skills</Badge>
        )}
      </div>

      {scores && typeof scores === "object" ? (
        <div className="space-y-2">
          {Object.entries(scores as Record<string, { score: number; notes?: string }>).map(([skill, data]) => {
            const clampedScore = Math.max(0, Math.min(data.score ?? 0, 100));
            const level = getSkillLevel(clampedScore);
            return (
              <div key={skill} className="space-y-0.5">
                <div className="flex items-center justify-between text-xs gap-2">
                  <span className="text-muted-foreground capitalize truncate">{skill.replace(/_/g, " ")}</span>
                  <div className="flex items-center gap-1.5 shrink-0">
                    <span className="font-semibold tabular-nums">{clampedScore}%</span>
                    <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${level.color}`}>
                      {level.label}
                    </span>
                  </div>
                </div>
                <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
                  <div
                    className="h-full rounded-full bg-score-skills transition-all"
                    style={{ width: `${clampedScore}%` }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No skill data available</p>
      )}

      {/* Missing skills shown in JD Aligned panel — removed here to avoid repetition */}
    </div>
  );
};

export default SkillsDetailPanel;

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { ChevronDown, ChevronUp } from "lucide-react";
import type { Result } from "@/pages/Index";

interface InterviewQuestionsPanelProps {
  result: Result;
}

const InterviewQuestionsPanel = ({ result: r }: InterviewQuestionsPanelProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const questions = r.interview_questions;

  if (!questions || !Array.isArray(questions) || questions.length === 0) return null;

  // First question is shown as "Interview Focus" in JD Aligned panel — show remaining here
  const remaining = questions.slice(1);
  if (remaining.length === 0) return null;

  return (
    <div>
      <Button
        variant="ghost"
        size="sm"
        className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground gap-1"
        onClick={() => setIsOpen(!isOpen)}
      >
        More Interview Questions ({remaining.length})
        {isOpen ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
      </Button>
      {isOpen && (
        <ol start={2} className="text-sm list-decimal list-inside space-y-1 text-muted-foreground mt-2 pl-2">
          {remaining.map((q: string, i: number) => <li key={i}>{q}</li>)}
        </ol>
      )}
    </div>
  );
};

export default InterviewQuestionsPanel;

