203→          {/* AI INSIGHT */}
204→          <div className="space-y-2">
205→            <span className="text-[10px] uppercase tracking-wider text-score-overall font-semibold flex items-center gap-1">
206→              <Lightbulb className="h-3 w-3" /> AI Insight
207→            </span>
208→
209→            {r.explanation_json?.why_ranked_here && (
