211→            )}
212→
213→            {/* Recommendation */}
214→            <div className={`p-2 rounded text-[11px] font-medium border ${PILL_CLS[rec.v]}`}>
215→              <span className="text-[9px] uppercase tracking-wider font-semibold block mb-0.5 opacity-70">Recommendation</span>
