33→      {scores && typeof scores === "object" ? (
34→        <div className="space-y-2">
35→          {Object.entries(scores as Record<string, { score: number; notes?: string }>).map(([skill, data]) => {
36→            const clampedScore = Math.max(0, Math.min(data.score ?? 0, 100));
37→            const level = getSkillLevel(clampedScore);
38→            return (
39→              <div key={skill} className="space-y-0.5">
40→                <div className="flex items-center justify-between text-xs gap-2">
