42→                  <div className="flex items-center gap-1.5 shrink-0">
43→                    <span className="font-semibold tabular-nums">{clampedScore}%</span>
44→                    <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${level.color}`}>
45→                      {level.label}
46→                    </span>
47→                  </div>
48→                </div>
49→                <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
50→                  <div
51→                    className="h-full rounded-full bg-score-skills transition-all"
52→                    style={{ width: `${clampedScore}%` }}
53→                  />
54→                </div>
55→              </div>
56→            );
57→          })}
58→        </div>
59→      ) : (
60→        <p className="text-xs text-muted-foreground">No skill data available</p>
61→      )}
62→
63→      {/* Missing skills shown in JD Aligned panel — removed here to avoid repetition */}
64→    </div>
