  4→interface Role {
  5→  title?: string;
  6→  company?: string;
  7→  start?: string;
  8→  end?: string;
  9→  description?: string;
 10→  type?: string;
 11→  employment_type?: string;
 12→}
 13→
 14→interface ExperiencePanelProps {
 15→  parsedJson: any;
 16→}
 17→
 18→/** Extract a 4-digit year from any date string format */
 19→const extractYear = (dateStr?: string): number | null => {
 20→  if (!dateStr) return null;
 21→  const match = dateStr.match(/\b(19|20)\d{2}\b/);
 22→  return match ? parseInt(match[0]) : null;
 23→};
 24→
 25→/** Check if a date string indicates "current/present" role */
 26→const isCurrent = (dateStr?: string): boolean => {
 27→  if (!dateStr) return false;
 28→  const lower = dateStr.toLowerCase().trim();
 29→  return lower === "current" || lower === "present" || lower === "now" || lower.includes("present") || lower.includes("current");
 30→};
 31→
 32→/** Compute duration in years between two date strings */
 33→const computeYears = (start?: string, end?: string): number => {
 34→  const startYear = extractYear(start);
 35→  if (!startYear) return 0;
 36→  const endYear = isCurrent(end) ? new Date().getFullYear() : extractYear(end);
 37→  if (!endYear) {
 38→    // If end is missing, try extracting a range from start string (e.g., "2021 – 2025")
 39→    const rangeMatch = start?.match(/\b((?:19|20)\d{2})\b.*\b((?:19|20)\d{2})\b/);
 40→    if (rangeMatch) {
 41→      return Math.max(0, parseInt(rangeMatch[2]) - parseInt(rangeMatch[1]));
 42→    }
 43→    return 0;
 44→  }
 45→  return Math.max(0, endYear - startYear);
 46→};
 47→
 48→const ExperiencePanel = ({ parsedJson }: ExperiencePanelProps) => {
 49→  const roles: Role[] = parsedJson?.roles_with_dates || parsedJson?.experience || [];
 50→
 51→  const totalYears = roles.length > 0
 52→    ? roles.reduce((sum, r) => sum + computeYears(r.start, r.end), 0)
 53→    : null;
 54→
 55→  return (
 56→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
 57→      <div className="flex items-center gap-2 mb-1">
 58→        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
 59→          <Briefcase className="h-3.5 w-3.5 text-purple-500" />
 60→        </div>
 61→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
 62→        {totalYears !== null && totalYears > 0 && (
 63→          <Badge variant="outline" className="ml-auto text-[10px]">{totalYears} yrs</Badge>
 64→        )}
 65→      </div>
 66→
 67→      {roles.length > 0 ? (
 68→        <div className="space-y-3">
 69→          {roles.slice(0, 4).map((role, i) => {
 70→            const startYear = extractYear(role.start);
 71→            const endYear = isCurrent(role.end) ? "Present" : extractYear(role.end);
 72→            const duration = startYear && endYear ? `${startYear} – ${endYear}` : role.start || "";
 73→            const years = computeYears(role.start, role.end);
 74→            const isCurrentRole = isCurrent(role.end);
 75→            const empType = role.employment_type || role.type;
 76→
 77→            return (
 78→              <div key={i} className="flex gap-2">
 79→                <div className="flex flex-col items-center mt-1">
 80→                  <div className={`w-2 h-2 rounded-full shrink-0 ${i === 0 ? "bg-purple-500" : "bg-muted-foreground/40"}`} />
 81→                  {i < Math.min(roles.length, 4) - 1 && <div className="w-px flex-1 bg-border mt-1" />}
 82→                </div>
 83→                <div className="space-y-0.5 min-w-0">
 84→                  <p className="text-xs font-medium text-foreground leading-tight truncate">{role.title || "Untitled Role"}</p>
 85→                  {role.company && (
 86→                    <p className="text-[11px] text-muted-foreground truncate">{role.company}</p>
 87→                  )}
 88→                  <div className="flex items-center gap-1.5 flex-wrap">
 89→                    {duration && <span className="text-[10px] text-muted-foreground">{duration}</span>}
 90→                    {years > 0 && <span className="text-[10px] text-muted-foreground">· {years} yr{years !== 1 ? "s" : ""}</span>}
 91→                    {isCurrentRole && (
 92→                      <Badge variant="outline" className="text-[9px] h-4 bg-emerald-500/10 text-emerald-600 border-emerald-200">Current</Badge>
 93→                    )}
 94→                    {empType && (
 95→                      <Badge variant="outline" className="text-[9px] h-4">{empType}</Badge>
 96→                    )}
 97→                  </div>
 98→                </div>
 99→              </div>
100→            );
101→          })}
102→          {roles.length > 4 && (
103→            <p className="text-[10px] text-muted-foreground">+{roles.length - 4} more roles</p>
104→          )}
105→        </div>
106→      ) : (
107→        <p className="text-xs text-muted-foreground">No experience data available</p>
108→      )}
109→    </div>
110→  );
111→};
112→
113→export default ExperiencePanel;
