import { Badge } from "@/components/ui/badge";
import { Briefcase } from "lucide-react";

interface Role {
  title?: string;
  company?: string;
  start?: string;
  end?: string;
  description?: string;
  type?: string;
  employment_type?: string;
}

interface ExperiencePanelProps {
  parsedJson: any;
}

/** Extract a 4-digit year from any date string format */
const extractYear = (dateStr?: any): number | null => {
  if (dateStr == null) return null;
  if (typeof dateStr === "number") return dateStr >= 1900 && dateStr <= 2100 ? dateStr : null;
  const match = String(dateStr).match(/\b(19|20)\d{2}\b/);
  return match ? parseInt(match[0]) : null;
};

/** Check if a date string indicates "current/present" role */
const isCurrent = (dateStr?: any): boolean => {
  if (dateStr == null) return false;
  const lower = String(dateStr).toLowerCase().trim();
  return lower === "current" || lower === "present" || lower === "now" || lower.includes("present") || lower.includes("current");
};

/** Compute duration in years between two date strings */
const computeYears = (start?: string, end?: string): number => {
  const startYear = extractYear(start);
  if (!startYear) return 0;
  const endYear = isCurrent(end) ? new Date().getFullYear() : extractYear(end);
  if (!endYear) {
    // If end is missing, try extracting a range from start string (e.g., "2021 – 2025")
    const rangeMatch = start ? String(start).match(/\b((?:19|20)\d{2})\b.*\b((?:19|20)\d{2})\b/) : null;
    if (rangeMatch) {
      return Math.max(0, parseInt(rangeMatch[2]) - parseInt(rangeMatch[1]));
    }
    return 0;
  }
  return Math.max(0, endYear - startYear);
};

const ExperiencePanel = ({ parsedJson }: ExperiencePanelProps) => {
  const rawRoles = parsedJson?.roles_with_dates ?? parsedJson?.experience;
  const roles: Role[] = Array.isArray(rawRoles) ? rawRoles : [];

  const totalYears = roles.length > 0
    ? roles.reduce((sum, r) => sum + computeYears(r.start, r.end), 0)
    : null;

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
          <Briefcase className="h-3.5 w-3.5 text-purple-500" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
        {totalYears !== null && totalYears > 0 && (
          <Badge variant="outline" className="ml-auto text-[10px]">{totalYears} yrs</Badge>
        )}
      </div>

      {roles.length > 0 ? (
        <div className="space-y-3">
          {roles.slice(0, 4).map((role, i) => {
            const startYear = extractYear(role.start);
            const endYear = isCurrent(role.end) ? "Present" : extractYear(role.end);
            const duration = startYear && endYear ? `${startYear} – ${endYear}` : role.start || "";
            const years = computeYears(role.start, role.end);
            const isCurrentRole = isCurrent(role.end);
            const empType = role.employment_type || role.type;

            return (
              <div key={i} className="flex gap-2">
                <div className="flex flex-col items-center mt-1">
                  <div className={`w-2 h-2 rounded-full shrink-0 ${i === 0 ? "bg-purple-500" : "bg-muted-foreground/40"}`} />
                  {i < Math.min(roles.length, 4) - 1 && <div className="w-px flex-1 bg-border mt-1" />}
                </div>
                <div className="space-y-0.5 min-w-0">
                  <p className="text-xs font-medium text-foreground leading-tight truncate">{role.title || "Untitled Role"}</p>
                  {role.company && (
                    <p className="text-[11px] text-muted-foreground truncate">{role.company}</p>
                  )}
                  <div className="flex items-center gap-1.5 flex-wrap">
                    {duration && <span className="text-[10px] text-muted-foreground">{duration}</span>}
                    {years > 0 && <span className="text-[10px] text-muted-foreground">· {years} yr{years !== 1 ? "s" : ""}</span>}
                    {isCurrentRole && (
                      <Badge variant="outline" className="text-[9px] h-4 bg-emerald-500/10 text-emerald-600 border-emerald-200">Current</Badge>
                    )}
                    {empType && (
                      <Badge variant="outline" className="text-[9px] h-4">{empType}</Badge>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
          {roles.length > 4 && (
            <p className="text-[10px] text-muted-foreground">+{roles.length - 4} more roles</p>
          )}
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No experience data available</p>
      )}
    </div>
  );
};

export default ExperiencePanel;

