          </div>
        </div>
      )}

      {/* Top skill chips */}
      {topSkills.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {topSkills.map((s) => (
            <span key={s.skill} className={`text-[10px] font-medium px-2 py-0.5 rounded-full border ${s.level.cls}`}>
              {s.skill.replace(/_/g, " ")} · {s.level.label}
            </span>
          ))}
        </div>
      )}

      {/* Gap rows with severity */}
      {(gapSkills.length > 0 || extraGaps.length > 0) && (
        <div className="space-y-1.5">
          {gapSkills.map((s) => (
            <div
