                <AlertTriangle className="h-3 w-3 shrink-0" />
                <span className="font-medium">{s.skill.replace(/_/g, " ")}</span>
              </div>
              <Badge variant="outline" className="text-[8px] uppercase bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800">
                Critical
              </Badge>
            </div>
          ))}
          {extraGaps.map((g, i) => (
            <div
              key={`eg-${i}`}
              className="flex items-center justify-between text-[11px] px-2.5 py-1.5 rounded-md border bg-amber-500/10 text-amber-700 border-amber-200 dark:text-amber-400 dark:border-amber-800"
            >
              <div className="flex items-center gap-1.5">
                <AlertTriangle className="h-3 w-3 shrink-0" />
                <span className="font-medium">{g}</span>
              </div>
              <Badge variant="outline" className="text-[8px] uppercase bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800">
                Preferred
              </Badge>
            </div>
          ))}
        </div>
      )}

      {/* Expandable full skill breakdown */}
      {entries.length > 0 && (
        <>
          <Button
            variant="ghost"
            size="sm"
            className="h-6 px-2 text-[10px] text-muted-foreground hover:text-foreground gap-1 w-full justify-center"
            onClick={() => setShowAll(!showAll)}
          >
            {showAll ? "Hide" : `See all ${skillCount} skills`}
            {showAll ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
          </Button>

          {showAll && (
            <div className="space-y-1.5 pt-1 border-t border-border">
              {visibleEntries.map((e) => (
                <div key={e.skill} className="flex items-center justify-between text-xs gap-2">
                  <span className="text-muted-foreground capitalize truncate">{e.skill.replace(/_/g, " ")}</span>
                  <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border shrink-0 ${e.level.cls}`}>
                    {e.level.label}
                  </span>
                </div>
              ))}
            </div>
          )}
        </>
      )}

      {skillCount === 0 && (
        <p className="text-xs text-muted-foreground">No skill data available</p>
      )}
    </div>
  );
};

export default SkillsDetailPanel;

