import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Cpu, ChevronDown, ChevronUp, AlertTriangle } from "lucide-react";
import type { Result } from "@/pages/Index";

interface SkillsDetailPanelProps {
  result: Result;
}

type SkillLevel = "Expert" | "Adv" | "Good" | "Mid" | "Low" | "Gap";

const getSkillLevel = (score: number): { label: SkillLevel; cls: string } => {
  if (score >= 90) return { label: "Expert", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (score >= 70) return { label: "Adv", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
  if (score >= 55) return { label: "Good", cls: "bg-teal-500/10 text-teal-600 border-teal-200 dark:text-teal-400 dark:border-teal-800" };
  if (score >= 40) return { label: "Mid", cls: "bg-yellow-500/10 text-yellow-700 border-yellow-200 dark:text-yellow-400 dark:border-yellow-800" };
  if (score >= 20) return { label: "Low", cls: "bg-orange-500/10 text-orange-600 border-orange-200 dark:text-orange-400 dark:border-orange-800" };
  return { label: "Gap", cls: "bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800" };
};

const getOverallLabel = (score: number): { text: string; cls: string } => {
  if (score >= 80) return { text: "Expert", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  if (score >= 65) return { text: "Advanced", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
  if (score >= 50) return { text: "Good", cls: "bg-teal-500/10 text-teal-600 border-teal-200 dark:text-teal-400 dark:border-teal-800" };
  if (score >= 30) return { text: "Mid", cls: "bg-yellow-500/10 text-yellow-700 border-yellow-200 dark:text-yellow-400 dark:border-yellow-800" };
  return { text: "Low", cls: "bg-orange-500/10 text-orange-600 border-orange-200 dark:text-orange-400 dark:border-orange-800" };
};

const SkillsDetailPanel = ({ result: r }: SkillsDetailPanelProps) => {
  const [showAll, setShowAll] = useState(false);
  const scores = r.category_scores_json;
  const gaps = Array.isArray(r.gaps_json) ? r.gaps_json.map(String) : [];
  const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.map(String) : [];

  // Parse and sort skills
  const entries = scores && typeof scores === "object" && !Array.isArray(scores)
    ? Object.entries(scores as Record<string, any>).map(([skill, data]) => {
        const score = data && typeof data === "object" ? (data.score ?? 0) : (typeof data === "number" ? data : 0);
        const clamped = Math.max(0, Math.min(score, 100));
        const level = getSkillLevel(clamped);
        return { skill, score: clamped, level };
      }).sort((a, b) => b.score - a.score)
    : [];

  const skillCount = entries.length;
  const strongCount = entries.filter((e) => e.score >= 55).length;
  const gapCount = entries.filter((e) => e.score < 20).length;

  // Overall match score
  const overallScore = skillCount > 0
    ? Math.round(entries.reduce((sum, e) => sum + e.score, 0) / skillCount)
    : 0;
  const overallLabel = getOverallLabel(overallScore);

  // Top skills (score >= 55) for chips — show max 4
  const topSkills = entries.filter((e) => e.score >= 55).slice(0, 4);

  // Gap skills for gap rows
  const gapSkills = entries.filter((e) => e.score < 20);

  // Also include gaps from gaps_json that aren't in category scores
  const scoreSkillNames = new Set(entries.map((e) => e.skill.toLowerCase().replace(/_/g, " ")));
  const extraGaps = [...missing, ...gaps]
    .filter((g) => !scoreSkillNames.has(g.toLowerCase()))
    .slice(0, 3);

  // Collapsed: show top chips + gaps only; Expanded: show all skills
  const visibleEntries = showAll ? entries : [];

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      {/* Header */}
      <div className="flex items-center gap-2 flex-wrap">
        <div className="w-6 h-6 rounded bg-score-skills/10 flex items-center justify-center">
          <Cpu className="h-3.5 w-3.5 text-score-skills" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Skills Detail</h4>
        <div className="flex items-center gap-1 ml-auto">
          {skillCount > 0 && (
            <Badge variant="outline" className="text-[10px]">{skillCount} skills</Badge>
          )}
        </div>
      </div>

      {/* Overall match score */}
      {skillCount > 0 && (
        <div className="flex items-center gap-3">
          <span className="text-xl font-bold tabular-nums text-foreground">{overallScore}%</span>
          <div className="flex-1">
            <div className="flex items-center gap-1.5 mb-1">
              <Badge variant="outline" className={`text-[9px] ${overallLabel.cls}`}>{overallLabel.text}</Badge>
              <span className="text-[9px] text-muted-foreground">{strongCount} strong · {gapCount} gap{gapCount !== 1 ? "s" : ""}</span>
            </div>
            <div className="flex gap-0.5">
              {entries.map((e, i) => (
                <div
                  key={i}
                  className={`h-1.5 rounded-full flex-1 ${
                    e.score >= 70 ? "bg-emerald-500" :
                    e.score >= 55 ? "bg-blue-500" :
                    e.score >= 40 ? "bg-yellow-500" :
                    e.score >= 20 ? "bg-orange-400" :
                    "bg-red-400"
                  }`}
