            </div>
            <div className="flex justify-between text-[8px] text-muted-foreground/50 mt-0.5">
              <span>Gap</span><span>Low</span><span>Mid</span><span>Adv</span><span>Expert</span>
            </div>
          </div>
        </div>
      )}

      {/* Top skill chips */}
      {topSkills.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {topSkills.map((s) => (
            <span key={s.skill} className={`text-[10px] font-medium px-2 py-0.5 rounded-full border ${s.level.cls}`}>
              {s.skill.replace(/_/g, " ")} · {s.level.label}
            </span>
          ))}
        </div>
      )}

      {/* Gap rows with severity */}
      {(gapSkills.length > 0 || extraGaps.length > 0) && (
        <div className="space-y-1.5">
          {gapSkills.map((s) => (
            <div
              key={s.skill}
              className="flex items-center justify-between text-[11px] px-2.5 py-1.5 rounded-md border bg-red-500/10 text-red-700 border-red-200 dark:text-red-400 dark:border-red-800"
            >
              <div className="flex items-center gap-1.5">
                <AlertTriangle className="h-3 w-3 shrink-0" />
                <span className="font-medium">{s.skill.replace(/_/g, " ")}</span>
              </div>
              <Badge variant="outline" className="text-[8px] uppercase bg-red-500/10 text-red-600 border-red-200 dark:text-red-400 dark:border-red-800">
                Critical
