import { useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Briefcase, ChevronDown, ChevronUp } from "lucide-react";

interface Role {
  title?: string;
  company?: string;
  start?: string;
  end?: string;
  description?: string;
  type?: string;
  employment_type?: string;
}

interface ExperiencePanelProps {
  parsedJson: any;
  matchedMustHaves?: string[];
}

/* ── Date helpers ─────────────────────────────────────────── */

/** Parse a date string into a rough Date (month-level) */
const parseDate = (dateStr?: any): Date | null => {
  if (dateStr == null) return null;
  const s = String(dateStr).trim();

  // Check "present/current"
  if (/present|current|now/i.test(s)) return new Date();

  // Try "MMM YYYY" or "MM/YYYY" or "YYYY"
  const monthNames: Record<string, number> = {
    jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5,
    jul: 6, aug: 7, sep: 8, oct: 9, nov: 10, dec: 11,
  };

  // "Jan 2023", "January 2023", "Jun 2022"
  const mmmYyyy = s.match(/([a-zA-Z]+)\s*(\d{4})/);
  if (mmmYyyy) {
    const mo = monthNames[mmmYyyy[1].slice(0, 3).toLowerCase()];
    if (mo !== undefined) return new Date(parseInt(mmmYyyy[2]), mo);
  }

  // "2023-01", "01/2023"
  const numDate = s.match(/(\d{1,2})[\/\-](\d{4})/);
  if (numDate) return new Date(parseInt(numDate[2]), parseInt(numDate[1]) - 1);

  // "2023"
  const yearOnly = s.match(/\b(19|20)\d{2}\b/);
  if (yearOnly) return new Date(parseInt(yearOnly[0]), 0);

  return null;
};

const isCurrent = (dateStr?: any): boolean => {
  if (dateStr == null) return false;
  return /present|current|now/i.test(String(dateStr));
};

/** Compute months between two dates */
const monthsBetween = (start: Date, end: Date): number => {
  return Math.max(0, (end.getFullYear() - start.getFullYear()) * 12 + (end.getMonth() - start.getMonth()));
};

/** Format months as "X yrs Y mos" or "X mos" */
const formatDuration = (months: number): string => {
  if (months <= 0) return "";
  const yrs = Math.floor(months / 12);
  const mos = months % 12;
  if (yrs === 0) return `${mos} mos`;
  if (mos === 0) return `${yrs} yr${yrs !== 1 ? "s" : ""}`;
  return `${yrs} yr${yrs !== 1 ? "s" : ""} ${mos} mos`;
};

/** Format date as "MMM YYYY" */
const formatDate = (d: Date): string => {
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  return `${months[d.getMonth()]} ${d.getFullYear()}`;
};

/** Get employment type label */
const getEmpType = (role: Role): { label: string; cls: string } | null => {
  const t = (role.employment_type || role.type || "").toLowerCase();
  if (t.includes("intern")) return { label: "Internship", cls: "bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800" };
  if (t.includes("contract") || t.includes("freelance")) return { label: "Contract", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" };
  if (t.includes("part")) return { label: "Part-time", cls: "bg-blue-500/10 text-blue-600 border-blue-200 dark:text-blue-400 dark:border-blue-800" };
  if (t.includes("full") || t === "") return { label: "Full-time", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" };
  return { label: t, cls: "bg-muted text-muted-foreground border-border" };
};

/** JD relevance tag */
type RelevanceTag = "jd_relevant" | "partially_relevant" | "low_relevance";
const RELEVANCE: Record<RelevanceTag, { label: string; cls: string }> = {
  jd_relevant: { label: "JD Relevant", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800" },
  partially_relevant: { label: "Partially Relevant", cls: "bg-amber-500/10 text-amber-600 border-amber-200 dark:text-amber-400 dark:border-amber-800" },
  low_relevance: { label: "Low Relevance", cls: "bg-muted/60 text-muted-foreground border-border" },
};

/* ── Component ────────────────────────────────────────────── */

const ExperiencePanel = ({ parsedJson, matchedMustHaves }: ExperiencePanelProps) => {
  const [showDetail, setShowDetail] = useState(false);
  const rawRoles = parsedJson?.roles_with_dates ?? parsedJson?.experience;
  const roles: Role[] = Array.isArray(rawRoles) ? rawRoles : [];
  const matchedLower = Array.isArray(matchedMustHaves) ? matchedMustHaves.map((m) => String(m).toLowerCase()) : [];

  // Parse dates for each role
  const parsed = roles.map((role) => {
    const startDate = parseDate(role.start);
    const endDate = parseDate(role.end) || (isCurrent(role.end) ? new Date() : null);
    const months = startDate && endDate ? monthsBetween(startDate, endDate) : 0;
    const empType = getEmpType(role);
    const isInternship = empType?.label === "Internship";
    const isCurrentRole = isCurrent(role.end);

    // JD relevance: check if role title/description matches any must-have
    const combined = `${role.title || ""} ${role.description || ""} ${role.company || ""}`.toLowerCase();
    let relevance: RelevanceTag = "low_relevance";
    const fullMatch = matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.filter((w) => combined.includes(w)).length >= Math.max(1, Math.floor(words.length * 0.5));
    });
    if (fullMatch) relevance = "jd_relevant";
    else if (matchedLower.some((m) => {
      const words = m.split(/\s+/).filter((w) => w.length > 3);
      return words.some((w) => combined.includes(w));
    })) relevance = "partially_relevant";

    return { ...role, startDate, endDate, months, empType, isInternship, isCurrentRole, relevance };
  });

  // Stat pills
  const totalMonths = parsed.reduce((sum, r) => sum + r.months, 0);
  const fullTimeMonths = parsed.filter((r) => !r.isInternship).reduce((sum, r) => sum + r.months, 0);
  const internMonths = parsed.filter((r) => r.isInternship).reduce((sum, r) => sum + r.months, 0);

  // Gap detection between consecutive roles
  const gaps: { afterIndex: number; months: number }[] = [];
  for (let i = 0; i < parsed.length - 1; i++) {
    const prev = parsed[i];
    const next = parsed[i + 1];
    if (prev.startDate && next.endDate) {
      const gapMonths = monthsBetween(next.endDate, prev.startDate);
      if (gapMonths >= 3) gaps.push({ afterIndex: i, months: gapMonths });
    }
  }
  const gapMap = new Map(gaps.map((g) => [g.afterIndex, g]));

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      {/* Header with stat pills */}
