          {fullTimeMonths > 0 && internMonths > 0 && (
            <>
              <Badge variant="outline" className="text-[9px] bg-emerald-500/10 text-emerald-600 border-emerald-200 dark:text-emerald-400 dark:border-emerald-800">
                {formatDuration(fullTimeMonths)} <span className="font-normal ml-0.5">Full-time</span>
              </Badge>
              <Badge variant="outline" className="text-[9px] bg-purple-500/10 text-purple-600 border-purple-200 dark:text-purple-400 dark:border-purple-800">
                {formatDuration(internMonths)} <span className="font-normal ml-0.5">Internship</span>
              </Badge>
            </>
          )}
        </div>
      </div>

      {/* Roles timeline */}
      {parsed.length > 0 ? (
        <div className="space-y-0">
          {parsed.slice(0, showDetail ? undefined : 4).map((role, i) => {
            const gap = gapMap.get(i);
            const dotOpacity = i === 0 ? "bg-purple-500" : i === 1 ? "bg-purple-400" : i === 2 ? "bg-purple-300" : "bg-muted-foreground/40";
            const rel = RELEVANCE[role.relevance];

            return (
              <div key={i}>
                <div className="flex gap-2 py-1.5">
                  {/* Timeline dot + line */}
                  <div className="flex flex-col items-center mt-1.5">
                    <div className={`w-2 h-2 rounded-full shrink-0 ${dotOpacity}`} />
                    {i < parsed.length - 1 && <div className="w-px flex-1 bg-border mt-1" />}
                  </div>

                  {/* Role content */}
                  <div className="flex-1 min-w-0 space-y-0.5">
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <p className="text-xs font-semibold text-foreground leading-tight">
                        {role.title || "Untitled Role"}
                      </p>
                      {role.empType && (
                        <span className={`text-[8px] font-semibold uppercase px-1.5 py-0.5 rounded border ${role.empType.cls}`}>
                          {role.empType.label}
                        </span>
                      )}
                    </div>
                    {role.company && (
                      <p className="text-[11px] text-muted-foreground">{role.company}</p>
                    )}
                    <div className="flex items-center gap-1.5 flex-wrap">
                      {role.startDate && (
                        <span className="text-[10px] text-muted-foreground">
                          {formatDate(role.startDate)} – {role.isCurrentRole ? "Present" : role.endDate ? formatDate(role.endDate) : ""}
                        </span>
