                      {role.months > 0 && (
                        <span className="text-[10px] font-medium text-emerald-600 dark:text-emerald-400">
                          {formatDuration(role.months)}
                        </span>
                      )}
                    </div>
                    {role.relevance !== "low_relevance" && (
