import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface PlatformConfig {
  max_resumes_per_job: number;
  max_file_size_mb: number;
  resume_retention_days: number;
  payg_per_resume_cost: number;
  topup_min_amount: number;
  topup_dodo_product_id: string | null;
}

const DEFAULTS: PlatformConfig = {
  max_resumes_per_job: 10,
  max_file_size_mb: 5,
  resume_retention_days: 30,
  payg_per_resume_cost: 0.07,
  topup_min_amount: 1,
  topup_dodo_product_id: null,
};

export const usePlatformConfig = () => {
  return useQuery({
    queryKey: ["platform_config"],
    queryFn: async (): Promise<PlatformConfig> => {
      // Uses the get_public_platform_config() SECURITY DEFINER function which
      // returns only non-sensitive columns. Direct table SELECT is now
      // restricted to admins only (platform_config RLS migration 20260324120000).
      const { data, error } = await (supabase as any).rpc("get_public_platform_config");
      if (error || !data || !data[0]) return DEFAULTS;
      return data[0] as PlatformConfig;
    },
    retry: false,
    placeholderData: DEFAULTS,
  });
};
